INSERT INTO cities (name, province, center_lat, center_lng, tagline, best_season) VALUES
('桂林', '广西', 25.27, 110.29, '山水甲天下，梯田与漓江都能徒步', '4-10月'),
('广州', '广东', 23.13, 113.26, '城市山林与从化乡村线，周末就能出发', '10-4月'),
('深圳', '广东', 22.55, 114.06, '海岸线资源最好的城市，东西冲最好走', '10-4月'),
('长沙', '湖南', 28.23, 112.94, '岳麓山下的烟火气，周边多是千米山', '3-5月/9-11月'),
('湘西', '湖南', 28.31, 109.74, '古城、峡谷与苗寨，玩法密度很高', '4-10月'),
('张家界', '湖南', 29.12, 110.48, '峰林天花板，景区线够走三天', '4-10月'),
('惠州', '广东', 23.11, 114.42, '山、海、温泉三种玩法一城打包', '10-5月'),
('郴州', '湖南', 25.77, 113.02, '雾漫小东江与丹霞山脊，性价比高', '4-10月'),
('韶关', '广东', 24.81, 113.6, '船底顶与丹霞山，广东最硬的山都在这里', '10-12月'),
('衡阳', '湖南', 26.89, 112.57, '南岳衡山，石阶古道与祝融峰云海', '全年'),
('清远', '广东', 23.68, 113.05, '英西峰林与八排山，喀斯特与草甸并存', '10-4月'),
