INSERT INTO spots (id, name, city_id, district, type, heat, ticket, hours, reason, lat, lng) VALUES
(1, '漓江·杨堤至兴坪', 1, '阳朔县', '江河', 96, '¥215', '4-6小时', '漓江最精华的20公里水路，九马画山、黄布倒影都在这一段，坐竹筏比大船更贴近山水。', 24.98, 110.47),
(2, '遇龙河竹筏', 1, '阳朔县', '江河', 92, '¥180', '2-3小时', '比漓江安静得多的支流，水浅滩多，竹筏顺流而下像在水墨画里穿行。', 24.78, 110.44),
(3, '龙脊梯田', 1, '龙胜县', '梯田', 94, '¥80', '1天', '从平安寨走到金坑大寨垂直落差近千米，5月灌水期和9月稻黄时最震撼。', 25.79, 110.11),
(4, '相公山观景台', 1, '阳朔县', '观景', 88, '¥60', '1-2小时', '15分钟登顶，俯瞰漓江第一湾，日出与云海同框的概率很高。', 24.97, 110.46),
(5, '猫儿山', 1, '兴安县', '山峰', 82, '¥70', '1天', '华南第一高峰2141米，山顶常有云海，山下漓江源头的原始森林很凉快。', 25.87, 110.45),
(6, '银子岩', 1, '荔浦市', '溶洞', 80, '¥65', '1.5小时', '三层溶洞走完约2公里，钟乳石密集，是雨天很稳的备选。', 24.63, 110.28),
(7, '十里画廊骑行', 1, '阳朔县', '田园', 85, '免费', '2-4小时', '月亮山到遇龙河一带的乡道，租辆电动车一路都是峰林。', 24.75, 110.47),
(8, '兴坪古镇', 1, '阳朔县', '古镇', 78, '免费', '2小时', '老码头、青石板街和20元人民币背景取景地都在镇上。', 24.94, 110.49),
(9, '八角寨', 1, '资源县', '丹霞', 76, '¥80', '半天', '一脚踏两省的丹霞峰林，龙头香那条脊线视野最好，人少景野。', 26.28, 110.72),
(10, '古东瀑布', 1, '灵川县', '瀑布', 72, '¥80', '3小时', '可以穿着草鞋踩着瀑布往上爬，夏天玩水首选。', 25.2, 110.42),
(11, '全州天湖', 1, '全州县', '高山湖泊', 68, '免费', '半天', '海拔1600米的高山湖泊群，草甸开阔，适合自驾露营。', 25.93, 110.98),
(12, '白云山', 2, '白云区', '山峰', 90, '¥5', '半天', '市区里就能爬的山，摩星岭看全城日落，全程石阶好走。', 23.18, 113.3),
(13, '沙面岛', 2, '荔湾区', '建筑', 88, '免费', '2小时', '150多栋欧式老建筑，江边树荫多，适合散步拍照。', 23.11, 113.24),
(14, '永庆坊', 2, '荔湾区', '街区', 86, '免费', '2小时', '西关骑楼改造的街区，粤剧博物馆和手作店值得慢慢逛。', 23.12, 113.24),
(15, '陈家祠', 2, '荔湾区', '古建', 84, '¥10', '1.5小时', '岭南建筑装饰的集大成者，砖雕木雕灰塑看一天都不腻。', 23.13, 113.24),
(16, '越秀公园', 2, '越秀区', '公园', 80, '免费', '2小时', '五羊石像和明代城墙都在园内，树荫密，遛娃遛老人都合适。', 23.14, 113.27),
(17, '华南植物园', 2, '天河区', '植物园', 78, '¥20', '半天', '国内最大的南亚热带植物园，夏季温室很出片。', 23.19, 113.36),
(18, '从化溪头村', 2, '从化区', '乡村', 82, '免费', '1天', '广州最美乡村，竹海溪流环绕，周边就是影古线徒步。', 23.75, 113.72),
(19, '石门国家森林公园', 2, '从化区', '森林', 79, '¥40', '1天', '石门红叶和天堂顶草甸，秋季自驾最舒服。', 23.62, 113.78),
(20, '莲花山', 2, '番禺区', '地质', 74, '¥54', '半天', '古采石场留下的悬崖峭壁，江边日落视野开阔。', 22.99, 113.51),
(21, '广州塔', 2, '海珠区', '地标', 89, '¥150', '2小时', '450米观景台看珠江新城夜景，畏高可以只逛花城广场。', 23.1, 113.32),
(22, '海珠湖', 2, '海珠区', '湿地', 76, '免费', '2小时', '环湖5公里跑走皆宜，候鸟季能看到白鹭。', 23.08, 113.32),
(23, '梧桐山', 3, '罗湖区', '山峰', 93, '免费', '半天', '深圳最高峰944米，泰山涧上凌云道下，山顶能同时看深圳和香港。', 22.58, 114.21),
(24, '七娘山', 3, '大鹏新区', '山峰', 88, '免费', '1天', '深圳第二高峰，全程野线爬升近千米，需结伴并带足水。', 22.55, 114.55),
(25, '大鹏所城', 3, '大鹏新区', '古城', 84, '免费', '2小时', '600年海防古城，青砖巷子里藏了不少小馆子。', 22.59, 114.55),
(26, '杨梅坑', 3, '大鹏新区', '海岸', 86, '免费', '半天', '深圳最美海岸线之一，骑行到鹿嘴山庄看日出。', 22.55, 114.6),
(27, '西冲海滩', 3, '大鹏新区', '海滩', 82, '¥30', '半天', '4公里长沙滩，夏季限流需提前预约，配套齐全。', 22.47, 114.57),
(28, '深圳湾公园', 3, '南山区', '湿地', 85, '免费', '2小时', '15公里滨海绿道，对岸就是香港元朗，日落骑行热门。', 22.51, 113.95),
(29, '人才公园', 3, '南山区', '公园', 83, '免费', '1.5小时', '深圳湾畔的环湖公园，人才星光桥和湖面倒影是拍后海天际线的正位。', 22.52, 113.94),
(30, '仙湖植物园', 3, '罗湖区', '植物园', 81, '¥15', '半天', '梧桐山脚的植物园，弘法寺和化石森林可以连逛。', 22.58, 114.17),
(31, '大梅沙', 3, '盐田区', '海滩', 77, '免费', '半天', '免费海滩，木栈道沿海可一路走到小梅沙。', 22.59, 114.31),
(32, '马峦山', 3, '坪山区', '瀑布', 79, '免费', '半天', '深圳少见的瀑布群，梅花季山脊开满白梅。', 22.63, 114.33),
(33, '观澜湖', 3, '龙华区', '度假', 70, '免费', '半天', '高尔夫和生态运动公园，适合带娃放电。', 22.71, 114.05),
(34, '岳麓山', 4, '岳麓区', '山峰', 92, '免费', '半天', '爱晚亭、麓山寺、云麓宫一路串起来，秋天红叶最好看。', 28.19, 112.94),
(35, '橘子洲', 4, '岳麓区', '江洲', 89, '免费', '2小时', '湘江中的长岛，青年毛泽东雕像和烟花季是重点。', 28.19, 112.96),
(36, '太平老街', 4, '天心区', '街区', 85, '免费', '2小时', '长沙小吃一条街，臭豆腐糖油粑粑边走边吃。', 28.19, 112.97),
(37, '湖南博物院', 4, '开福区', '博物馆', 90, '免费', '3小时', '马王堆汉墓陈列是必看，需提前在公众号预约。', 28.21, 112.99),
(38, '大围山', 4, '浏阳市', '山峰', 78, '¥60', '1天', '浏阳河源头，4月杜鹃花海，冬季有雾凇。', 28.42, 114.08),
(39, '石燕湖', 4, '雨花区', '湖泊', 72, '¥100', '半天', '玻璃桥和丛林穿越，亲子项目多。', 28.03, 113.02),
(40, '铜官窑古镇', 4, '望城区', '古镇', 70, '¥120', '半天', '唐代窑址上新建的古镇，陶瓷手作体验不错。', 28.45, 112.81),
(41, '洋湖湿地', 4, '岳麓区', '湿地', 74, '免费', '2小时', '城市湿地公园，芦苇季和花海适合散步。', 28.13, 112.92),
(42, '黑麋峰', 4, '望城区', '山峰', 68, '¥40', '半天', '长沙近郊的滑翔伞基地，山顶风大视野好。', 28.35, 112.93),
(43, '凤凰古城', 5, '凤凰县', '古城', 93, '免费', '1天', '沱江吊脚楼与虹桥夜景，清晨无人时最美。', 27.95, 109.6),
(44, '芙蓉镇', 5, '永顺县', '古镇', 85, '¥100', '半天', '挂在瀑布上的千年古镇，雨后水量最壮观。', 28.66, 109.94),
(45, '德夯大峡谷', 5, '吉首市', '峡谷', 84, '¥100', '半天', '流纱瀑布和问天台，苗寨演出值得看一场。', 28.29, 109.62),
(46, '矮寨大桥', 5, '吉首市', '地标', 82, '¥120', '2小时', '355米高差的悬索桥，玻璃栈道视角震撼。', 28.33, 109.6),
(47, '红石林', 5, '古丈县', '地质', 76, '¥80', '半天', '4.5亿年前的海底石林，红色岩层随天气变色。', 28.63, 109.91),
(48, '边城茶峒', 5, '花垣县', '古镇', 74, '免费', '半天', '沈从文笔下的边城，拉拉渡还在，一脚踏三省。', 28.51, 109.29),
(49, '坐龙峡', 5, '古丈县', '峡谷', 72, '¥80', '半天', '要抓铁链踩木梯逆溪而上的峡谷，湿滑需谨慎。', 28.63, 109.95),
(50, '猛洞河漂流', 5, '永顺县', '漂流', 73, '¥180', '半天', '十里画廊漂流，夏季水量足时最爽。', 28.72, 109.9);
INSERT INTO spots (id, name, city_id, district, type, heat, ticket, hours, reason, lat, lng) VALUES
(51, '老司城', 5, '永顺县', '遗址', 68, '¥80', '3小时', '土司王朝八百年都城遗址，世界文化遗产。', 29, 109.9),
(52, '张家界国家森林公园', 6, '武陵源区', '峰林', 97, '¥228', '1-2天', '袁家界哈利路亚山和金鞭溪，砂岩峰林世界罕见。', 29.33, 110.43),
(53, '天门山', 6, '永定区', '山峰', 94, '¥278', '半天', '999级天梯、玻璃栈道和盘山公路，索道直接上山。', 29.05, 110.48),
(54, '天子山', 6, '武陵源区', '峰林', 92, '免费', '1天', '西海石林和御笔峰，日出观景台在贺龙公园附近。', 29.39, 110.44),
(55, '张家界大峡谷', 6, '慈利县', '峡谷', 86, '¥259', '半天', '玻璃桥横跨峡谷300米，蹦极和滑索都有。', 29.29, 110.72),
(56, '黄龙洞', 6, '武陵源区', '溶洞', 80, '¥100', '2小时', '洞中有河可乘船，定海神针石笋高19米。', 29.36, 110.6),
(57, '宝峰湖', 6, '武陵源区', '湖泊', 78, '¥96', '2小时', '高峡平湖，乘船听山歌，是整个行程里最安静的一站。', 29.32, 110.55),
(58, '金鞭溪', 6, '武陵源区', '溪谷', 88, '免费', '3小时', '7.5公里平缓溪谷，全程树荫，猴子多注意背包。', 29.34, 110.45),
(59, '杨家界', 6, '武陵源区', '峰林', 83, '免费', '1天', '乌龙寨和天波府一线险峻，人比袁家界少很多。', 29.35, 110.38),
(60, '七星山', 6, '永定区', '山峰', 70, '¥120', '1天', '海拔1528米的台地，云海和高山草甸，索道较新。', 29.1, 110.44),
(61, '罗浮山', 7, '博罗县', '山峰', 88, '¥55', '1天', '道教十大名山，飞云顶1296米，全程石阶约4小时。', 23.28, 114.06),
(62, '双月湾', 7, '惠东县', '海岸', 90, '免费', '半天', '两弯月牙海滩背靠背，观景台看全景最出片。', 22.72, 114.88),
(63, '巽寮湾', 7, '惠东县', '海滩', 85, '免费', '半天', '沙质细白，出海和海钓项目多，夏季度假热门。', 22.71, 114.74),
(64, '南昆山', 7, '龙门县', '森林', 84, '免费', '1天', '北回归线上的绿洲，竹林瀑布和温泉民宿集群。', 23.63, 113.85),
(65, '惠州西湖', 7, '惠城区', '湖泊', 80, '免费', '2小时', '苏东坡谪居地，六湖九桥十八景，散步很舒服。', 23.09, 114.4),
(66, '象头山', 7, '博罗县', '森林', 72, '免费', '1天', '惠州野线聚集地，溪谷溯溪和山脊线都有。', 23.3, 114.3),
(67, '黑排角', 7, '惠东县', '海岸', 86, '免费', '半天', '黑色礁石与白色浪花对比强烈，海岸线徒步约8公里。', 22.66, 114.95),
(68, '大亚湾', 7, '大亚湾区', '海岛', 75, '免费', '半天', '岛屿多，可坐船上岛露营，注意防晒。', 22.75, 114.55),
(69, '东江湖·小东江', 8, '资兴市', '湖泊', 95, '¥100', '半天', '4-10月清晨雾漫小东江，渔夫撒网是经典画面。', 25.98, 113.28),
(70, '高椅岭', 8, '苏仙区', '丹霞', 89, '免费', '3小时', '红岩绿水的高椅背山脊，走一圈约5公里，日落最好。', 25.99, 113.03),
(71, '莽山', 8, '宜章县', '山峰', 82, '¥100', '1天', '南岭山脉原始森林，五指峰栈道和云海，冬季有冰挂。', 24.93, 112.85),
(72, '飞天山', 8, '苏仙区', '丹霞', 80, '¥80', '半天', '丹霞地貌配翠江竹筏，睡美人山形很形象。', 25.9, 113.1),
(73, '仰天湖草原', 8, '北湖区', '草原', 78, '¥60', '半天', '海拔1300米的高山草原，风车和马群，露营看星星。', 25.45, 112.97),
(74, '板梁古村', 8, '永兴县', '古村', 70, '¥40', '2小时', '600年湘南古民居群，青砖天井保存完整。', 26.02, 113.3),
(75, '苏仙岭', 8, '苏仙区', '山峰', 72, '¥40', '半天', '城边小山，桃花居和三绝碑，1小时可登顶。', 25.8, 113.03),
(76, '便江', 8, '永兴县', '江河', 68, '免费', '半天', '丹霞夹江的十里画廊，可骑行可乘船。', 26.13, 113.28);
