INSERT INTO routes (id, name, province, city_id, terrain, level, level_text, distance_km, climb_m, days, season, heat, is_loop, hours_text, real_km, max_ele, min_ele, `desc`, tips, access_hsr, access_rail, access_bus, access_car, naming_json) VALUES
(1, '船底顶·罗新线', '广东', 9, '高山草甸', 'hard', '难', 30.5, 1650, '2天', '10-12月', 96, 0, '2 天', 22.3, 1583, 111, '广东驴友的“毕业线”。从曲江罗坑镇上山，经坪坑、大坝山峡谷、碎石坡登顶 1586 米的船底顶，再从新洞村下山。草坡与碎石坡交替，最后一段塌方区需要手脚并用。', '坪坑之后全程无补给；雨季塌方区禁行；山顶夜间接近 0℃ 且风大，必须带硬壳与保暖层。', '广州南→韶关站（约 50 分钟），韶关站包车至罗坑镇约 1 小时 40 分（约 260 元/车）。', '韶关东站（普速）下车，站前广场拼车到罗坑镇约 90 分钟。', '韶关汽车站→曲江/罗坑班车，每天 4-5 班，末班 16:30，下车后步行 20 分钟到登山口。', '导航“罗坑镇人民政府”，镇上可停车过夜（10-20 元/天）。', NULL),
(2, '船底顶·联山B线', '广东', 9, '高山草甸', 'hard', '难', 26, 1490, '2天', '10-12月', 84, 0, '8-10 小时', 27.1, 1586, 109, '从联山方向上山，坡度更陡但路程短，适合体力好、想避开罗坑长机耕道的队伍。下山走坪坑、罗坑，全程以草坡和防火带为主。', '联山段岔路多，务必带轨迹；无水源段长达 8 km。', '广州南→韶关站，包车至联山约 2 小时。', '韶关东站拼车至联山村约 100 分钟。', '韶关→曲江班车转罗坑，联山路口下车步行 3 km。', '导航“曲江联山小学”，村口可停车。', NULL),
(3, '大南山', '广东', 7, '高山草甸', 'mid', '中', 15.6, 1110, '1天', '11-12月', 88, 1, '6-8 小时', 9.5, 1107, 117, '万亩草甸铺在海拔 1000 米的山脊上，视野开阔没有遮挡，秋冬金色草浪最好看。环线走完约 6 小时，是惠州最出片的草甸线。', '山脊无水源，按 2L/人备水；下午雷雨多发，尽量上午登顶。', '深圳北→惠东站（约 40 分钟），打车至龙岩寺约 50 分钟（80-100 元）。', '惠州站→惠东班车，再转摩的至龙岩寺。', '惠东汽车站→安墩/宝口班车，龙岩寺路口下。', '导航“惠东龙岩寺”，寺前空地免费停车。', NULL),
(4, '白云嶂·银瓶嘴双峰', '广东', 7, '高山草甸', 'mid', '中', 12.8, 1020, '1天', '全年', 85, 0, '4-6 小时', 10.3, 1003, 92, '两座千米峰连穿，山脊起伏温和，是很多人第一次千米山的体验路线。天气好时能同时看到东莞、惠州、深圳三城。', '银瓶嘴下撤点较多，可按体力随时缩短；山脊风大，带薄风衣。', '深圳北→惠州南站，打车 40 分钟到白云嶂山脚。', '惠州站→新圩方向班车，白云嶂路口下。', '惠阳汽车站→新圩镇公交，再步行 2 km。', '导航“白云嶂森林公园”，山脚停车场 10 元/天。', NULL),
(5, '罗浮山·飞云顶', '广东', 7, '森林古道', 'mid', '中', 14.2, 1390, '1天', '10-4月', 84, 0, '6-8 小时', 4.4, 1298, 63, '道教十大名山之一。从朱明洞景区走古道上飞云顶 1296 米，是惠州最高点，下山后可以直接去山脚泡温泉。', '古道石阶湿滑，登山杖有用；山顶风大备薄外套；景区 17:00 后停止入园。', '广州东→罗浮山站（约 40 分钟），站前打车 15 分钟到朱明洞。', '惠州站→博罗班车，转罗浮山景区公交。', '博罗汽车站→罗浮山专线，20 分钟一班。', '导航“罗浮山朱明洞景区停车场”，20 元/天。', NULL),
(6, '黑排角海岸线', '广东', 7, '海岸礁石', 'easy', '易', 8.4, 100, '半天', '10-5月', 86, 0, '2-4 小时', 14.7, 23, 2, '黑色礁石配白浪，是惠州最出片的海岸线。部分路段要等退潮才能通过，出发前一定看潮汐表。', '涨潮时不要硬闯礁石段；穿防滑鞋，别穿沙滩鞋；全程无补给。', '深圳北→惠东站，打车至平海古城约 40 分钟。', '惠州站→惠东班车，转平海镇公交。', '惠东汽车站→平海班车（30 分钟一班，约 50 分钟）。', '导航“平海古城”，城外可停车。', NULL),
(7, '东西冲海岸线', '广东', 3, '海岸礁石', 'easy', '易', 10.2, 120, '1天', '10-4月', 89, 0, '2-4 小时', 5.5, 81, 3, '深圳最经典的海岸线，礁石、沙滩、崖壁交替出现，中段需要拉绳下降，很多人第一次海岸线徒步都选这里。', '周末人多，建议 8 点前进山；拉绳段注意让行；西涌需预约入园。', '深圳北站→地铁 3 号线到双龙，转公交 M471 至东涌。', '深圳站→地铁 1 号线转 3 号线，同上市区公交。', '大鹏中心公交站乘 M471/M457 至东涌村。', '导航“东涌沙滩停车场”，旺季需预约（i 深圳）。', NULL),
(8, '大鹿港海岸线', '广东', 3, '海岸礁石', 'mid', '中', 11.5, 120, '1天', '10-4月', 82, 0, '2-4 小时', 12.9, 72, 2, '人少水清的野海岸，中段有需要攀爬的岩壁，比东西冲更野一些，也因此保留了很干净的海湾。', '戴手套，手机装防水袋；全程无补给；不建议单人前往。', '深圳北→地铁至大鹏，转 M471 到西涌。', '深圳站→地铁 3 号线双龙站→公交 M457。', '大鹏中心→西涌的 M232，西涌一号浴场下。', '导航“西涌海滩”，停车 30 元/天。', NULL),
(9, '七娘山', '广东', 3, '山峰野线', 'mid', '中', 9.6, 940, '1天', '10-4月', 88, 0, '2-4 小时', 4.5, 870, 8, '深圳第二高峰 869 米，全程野线爬升近千米，山顶可俯瞰大鹏半岛与香港东平洲，是深圳最硬的一日线之一。', '需结伴并带足水；山脊无遮蔽；部分段落需拉绳。', '深圳北→地铁至大鹏中心，转 M471。', '深圳站→地铁 3 号线双龙，转 818 路。', '大鹏中心→地质公园 M457，终点下。', '导航“大鹏半岛国家地质公园”，停车 15 元/天。', NULL),
(10, '梧桐山·泰山涧', '广东', 3, '溪谷石阶', 'mid', '中', 10.8, 1010, '半天', '全年', 93, 0, '4-6 小时', 5.1, 943, 42, '深圳最高峰 944 米。泰山涧上、凌云道下是最经典的城市登山组合，山顶能同时看深圳与香港。', '周末 9 点后山顶人挤人；溪谷段雨后水量大，注意湿滑。', '深圳北→地铁 4 号线转 2 号线梧桐山南站。', '深圳站→地铁 1 号线转 2 号线梧桐山南站 C 口。', '211 路、M445 至梧桐山总站。', '导航“梧桐山南门停车场”，周末需早到。', NULL),
(11, '马峦山瀑布群', '广东', 3, '溪谷瀑布', 'easy', '易', 12, 360, '半天', '4-10月', 79, 0, '2-4 小时', 15.9, 321, 5, '深圳少见的瀑布群，沿溪谷一路上行，梅花季山脊开满白梅。终点可接大梅沙，走完直接下海。', '雨后水量大最美，但石面滑；防蚊液必备。', '深圳北→地铁 8 号线小梅沙站。', '深圳站→地铁 1 号线转 8 号线。', 'M362、M444 至小梅沙。', '导航“小梅沙停车场”，旺季需预约。', NULL),
(12, '排牙山', '广东', 3, '山脊岩壁', 'mid', '中', 11.2, 780, '1天', '10-4月', 76, 0, '4-6 小时', 10.1, 709, 12, '山脊像一排牙齿，两侧是陡崖，是深圳最刺激的山脊线。部分段落需要拉绳，恐高者慎入。', '必须结伴，带 20 米辅绳；大风天不要上山脊。', '深圳北→地铁至大鹏中心转 M457。', '深圳站→地铁 3 号线双龙转 818。', 'M457 至大鹏所城站。', '导航“大鹏所城停车场”。', NULL),
(13, '英西峰林走廊', '广东', 11, '喀斯特田园', 'easy', '易', 18, 160, '1天', '10-4月', 80, 0, '4-6 小时', 7.8, 183, 88, '“小桂林”之称的峰林走廊，从九龙镇走到黄花镇，一路喀斯特峰丛、稻田和古桥，几乎没有爬升，适合轻装慢走。', '夏季稻田灌水时倒影最美；乡道有农用车，靠边行走。', '广州南→英德西站（约 30 分钟），打车至九龙镇 50 分钟。', '英德站→九龙镇班车（约 1 小时）。', '英德汽车站→九龙班车，每小时一班。', '导航“九龙镇”，镇口可停车。', NULL),
(14, '丹霞山·长老峰', '广东', 9, '丹霞地貌', 'mid', '中', 9.8, 360, '1天', '10-4月', 83, 1, '2-4 小时', 3.4, 408, 87, '世界自然遗产丹霞山的核心线路，长老峰、海螺峰、宝珠峰三峰连穿，红色砂砾岩在夕阳下最红。', '景区内禁止野炊；观日亭看日出需 5:30 前上山。', '广州南→韶关站（50 分钟），转景区直通车 50 分钟。', '韶关东站→丹霞山旅游专线（约 1 小时）。', '韶关汽车客运东站→丹霞山班车，20 分钟一班。', '导航“丹霞山外山门票站”，停车 15 元/天。', NULL),
(15, '广东大峡谷', '广东', 9, '峡谷', 'mid', '中', 7.6, 390, '半天', '全年', 74, 0, '2-4 小时', 3.9, 640, 298, '乳源大峡谷深 300 余米，谷底溪流与瀑布成群，从谷口下到谷底再爬升，台阶近 3000 级，膝盖压力大。', '下谷 1386 级台阶，回程更累；带护膝与登山杖。', '广州南→韶关站，包车至大峡谷约 2 小时。', '韶关东站→乳源班车，转大峡谷专线。', '乳源汽车站→大峡谷班车，每天 3 班。', '导航“广东大峡谷景区”，停车 10 元。', NULL),
(16, '天堂顶', '广东', 2, '森林山峰', 'mid', '中', 14.5, 1150, '1天', '10-4月', 81, 0, '4-6 小时', 11.9, 1207, 120, '广州最高峰 1210 米，从化流溪河林场上山，穿越竹林、灌木与草甸，山顶可望五指山与流溪河水库。', '山顶无水源；竹林段岔路多，跟紧路标。', '广州南→从化站（地铁 14 号线），转公交至良口。', '广州站→从化汽车站班车，转良口镇公交。', '从化汽车站→良口班车，20 分钟一班。', '导航“流溪河国家森林公园”，停车 10 元。', NULL),
(17, '云髻山', '广东', 9, '森林山峰', 'mid', '中', 12.6, 1280, '1天', '10-4月', 77, 0, '4-6 小时', 5.2, 1440, 258, '新丰云髻山主峰 1438 米，山体像发髻，秋季红叶与云海出名，是粤北性价比较高的一日线。', '山顶风大；景区内部分路段无信号。', '广州南→韶关站，转新丰班车 2 小时。', '韶关东站→新丰班车，再打车 20 分钟。', '新丰汽车站→云髻山班车，每天 5 班。', '导航“云髻山景区”，停车 10 元。', NULL),
(18, '八排山', '广东', 11, '高山草甸', 'hard', '难', 22, 1260, '2天', '9-12月', 71, 0, '8-10 小时', 6.3, 1435, 317, '粤桂交界的高山草甸群，八座山峰连绵排开，秋季草浪金黄，人少景野，是广东少见的重装线。', '全程无补给，需背水；草甸无遮蔽，雷雨天危险。', '广州南→连州站（约 1.5 小时），包车至上帅镇 1 小时。', '连州站→连山班车，转上帅镇。', '连山汽车站→上帅班车，每天 3 班。', '导航“连山上帅镇”，镇上可停车。', NULL),
(19, '通天蜡烛', '广东', 11, '山峰草甸', 'mid', '中', 9.4, 1040, '半天', '10-4月', 68, 0, '4-6 小时', 1.5, 1045, 118, '佛冈最高峰 1046 米，因山形像蜡烛得名。路程短、爬升集中，是广州周边练腿的热门半日线。', '山顶无遮蔽；雨后土路很滑。', '广州南→清远站，打车至石角村 50 分钟。', '清远站→佛冈班车，转水头镇公交。', '佛冈汽车站→水头镇班车，再步行 3 km。', '导航“佛冈石角村”，村口停车。', NULL),
(20, '南岭·石坑崆', '广东', 9, '原始森林', 'hard', '难', 24, 1580, '2天', '5-10月', 73, 0, '8-10 小时', 6.1, 1904, 499, '广东最高峰 1902 米，位于南岭国家级自然保护区。从乳阳林场经亲水谷、瀑布群上到石坑崆，原始森林遮天蔽日。', '保护区需提前报备；山中多雨雾，务必带轨迹与对讲。', '广州南→韶关站，包车至乳阳约 2.5 小时。', '韶关东站→乳源班车，转乳阳林场。', '乳源汽车站→乳阳班车，每天 2 班。', '导航“南岭国家森林公园”，停车 20 元/天。', NULL);
INSERT INTO routes (id, name, province, city_id, terrain, level, level_text, distance_km, climb_m, days, season, heat, is_loop, hours_text, real_km, max_ele, min_ele, `desc`, tips, access_hsr, access_rail, access_bus, access_car, naming_json) VALUES
(21, '万时山', '广东', 9, '高山草甸', 'mid', '中', 16.5, 1460, '1天', '9-12月', 69, 0, '6-8 小时', 7, 1559, 259, '粤湘交界的高山草甸，主峰 1559 米，山脊一路开阔，秋季草黄时非常出片，人少且免费。', '山脊无水源；从湖南方向上山更近。', '广州南→韶关站，转仁化班车，再包车至城口。', '韶关东站→仁化班车，转城口镇。', '仁化汽车站→城口班车，30 分钟一班。', '导航“仁化城口镇”，镇上停车。', NULL),
(22, '观音山·王山寺', '广东', 11, '森林古道', 'easy', '易', 8, 590, '半天', '全年', 66, 0, '2-4 小时', 1.6, 583, 58, '清远观音山以王山寺古道闻名，全程林荫石阶，山顶有天然观音石像，适合新手与亲子。', '石阶青苔多，雨后慢行；寺内可补水。', '广州南→清远站，打车 30 分钟到王山寺。', '清远站→源潭班车，转王山寺。', '清远汽车站→高田班车，王山寺路口下。', '导航“清远王山寺”，寺前停车。', NULL),
(23, '岳麓山·桃花岭穿越', '湖南', 4, '城市山', 'easy', '易', 12.6, 300, '1天', '全年', 86, 0, '2-4 小时', 8, 301, 43, '起点是湖南大学东方红广场，终点是梅溪湖，中间依次翻过岳麓山主峰和桃花岭两片山地——名字里的「岳麓山」「桃花岭」是这条线翻越的对象，不是起点和终点。全程 12.6 km、累计爬升约 520 m，石阶与林荫土路交替，是长沙下班后拉练的固定路线。', '景区段游客多，注意让行；桃花岭段部分为野径，跟紧路标；地铁 2 号线可直达两端。', '长沙南站→地铁 4 号线（湖南大学站）约 35 分钟，2 号口出即起点。', '长沙站→地铁 2 号线转 4 号线，湖南大学站下。', '立珊专线、旅 1 路至湖南大学站。', '导航“湖南大学东方红广场”，周边停车位紧张，建议地铁。', '{"lead":"这条线的起点不是岳麓山，终点也不是桃花岭，名字容易让人误会。","actual":"实际起点 · 湖南大学东方红广场　→　实际终点 · 梅溪湖","rows":[["名称里的「岳麓山」","指中途翻越的岳麓山主峰一带（爱晚亭—麓山寺—山顶电视塔），是途经段，不是起点"],["名称里的「桃花岭」","指中途穿越的桃花岭景区（垭口—水库）野径段，是途经段，不是终点"],["实际起点","湖南大学东方红广场（地铁 4 号线湖南大学站 2 号口，步行约 6 分钟）"],["实际终点","梅溪湖（地铁 2 号线梅溪湖东站，出站即到湖边，可直接收尾）"]],"why":"长沙本地口语把这条线叫「岳麓山穿桃花岭」，写成线路名时压缩成「岳麓山·桃花岭」，久而久之被读成「岳麓山进、桃花岭出」。按那个理解去岳麓山景区大门找起点，会多绕约 2 km 才接上正线；也有人把终点定在桃花岭景区门口，少走最后下到梅溪湖的 3.5 km 缓坡。"}'),
(24, '衡山·经典登顶线', '湖南', 10, '石阶古道', 'mid', '中', 12.8, 1330, '1天', '全年', 94, 0, '4-6 小时', 7.8, 1299, 111, '南岳衡山最正统的登顶路线：南岳大庙起步，经华严湖、忠烈祠、半山亭、南天门直上祝融峰 1300 米。全程石阶，香客与驴友同路，云海与日出是最大回报。', '石阶连续，膝盖压力大，登山杖必备；山顶比山下低 8-10℃；旺季索道排队 1 小时以上。', '衡山西站→南岳景区专线巴士（约 25 分钟，10 元），终点南岳大庙。', '衡阳站→南岳班车（约 50 分钟），或打车 100 元。', '衡阳中心汽车站→南岳，20 分钟一班，末班 18:00。', '导航“南岳大庙停车场”，20-30 元/天。', NULL),
(25, '衡山·曾国藩古道', '湖南', 10, '古道', 'mid', '中', 16.5, 1310, '1天', '3-11月', 78, 0, '6-8 小时', 12.9, 1302, 107, '从衡山后山店门镇起步，走曾国藩修的石板古道经白云峰、南天门上祝融峰，再从南岳大庙下山。人少、原始，是衡山最有味道的穿越线。', '古道部分石板松动；后山无补给，需自带 2L 水；下山可坐景区车省膝盖。', '衡山西站→打车至店门镇约 30 分钟（50 元）。', '衡阳站→店门镇班车，约 40 分钟一班。', '衡阳汽车站→店门班车，最早 6:30。', '导航“衡山县店门镇”，镇口可停车。', NULL),
(26, '衡山·水帘洞—祝融峰', '湖南', 10, '溪谷石阶', 'mid', '中', 13.2, 1230, '1天', '4-10月', 72, 0, '4-6 小时', 8.5, 1301, 261, '从水帘洞景区上山，经烟霞峰、半山亭到祝融峰。前半段溪谷瀑布凉快，后半段石阶陡上，夏天走比经典线舒服。', '溪谷段雨后水量大，石面滑；水帘洞景区需单独购票。', '衡山西站→南岳景区专线，转水帘洞景区接驳。', '衡阳站→南岳班车，南岳镇转景区车。', '南岳镇→水帘洞景区公交，10 分钟。', '导航“南岳水帘洞景区”，停车 10 元。', NULL),
(27, '张家界·金鞭溪—袁家界', '湖南', 6, '峰林溪谷', 'easy', '易', 14.5, 660, '1天', '全年', 95, 0, '4-6 小时', 11.7, 1052, 478, '从森林公园门票站沿金鞭溪走到水绕四门，再乘百龙天梯上袁家界看“哈利路亚山”。溪谷段全程平缓林荫，是张家界最轻松的精华走法。', '溪谷猴子多，别手拿食物；百龙天梯旺季排队 1 小时，建议 8 点前进谷。', '张家界西站→景区直通车至森林公园门票站（约 50 分钟，12 元）。', '张家界站→森林公园班车（约 40 分钟）。', '张家界中心汽车站→森林公园，20 分钟一班。', '导航“张家界国家森林公园门票站”，停车 30 元/天。', NULL),
(28, '张家界·天子山—十里画廊', '湖南', 6, '峰林', 'mid', '中', 16, 770, '1天', '4-11月', 88, 0, '4-6 小时', 27.5, 1200, 519, '从十里画廊进山，经卧龙岭上天子山贺龙公园，看御笔峰、西海石林后从袁家界下山。是张家界峰林最集中的一条穿越线。', '卧龙岭台阶近 3000 级；山顶温差大；环保车末班 18:00。', '张家界西站→武陵源标志门直通车 40 分钟。', '张家界站→武陵源班车，转景区环保车。', '武陵源汽车站→标志门，5 分钟一班。', '导航“武陵源标志门停车场”。', NULL),
(29, '天门山·天门洞天梯', '湖南', 6, '山峰栈道', 'mid', '中', 9.8, 1510, '半天', '全年', 90, 0, '4-6 小时', 9.8, 1520, 179, '索道上山，走鬼谷栈道、玻璃栈道到天门山顶，再下 999 级天梯到天门洞。天门洞的穿山溶洞与盘山公路是张家界的另一张名片。', '玻璃栈道需另付 5 元鞋套；天梯下行对膝盖不友好，可坐扶梯（¥32）。', '张家界西站→打车至索道下站 20 分钟（30 元）。', '张家界站→公交 4 路至天门山索道站。', '市区 4 路、10 路公交直达索道下站。', '导航“天门山索道下站停车场”，30 元/天。', NULL),
(30, '莽山·五指峰', '湖南', 8, '原始森林', 'mid', '中', 13.5, 1180, '1天', '4-11月', 82, 0, '4-6 小时', 9.8, 1751, 698, '南岭山脉保存最完整的原始森林之一，五指峰栈道悬在崖壁上，云海与冰挂都出名。冬天是广东周边少数能看雾凇的地方。', '山上多雾，带防风外套；冬季栈道结冰需冰爪。', '广州南→郴州西站（1.5 小时），转莽山直通车 2 小时。', '郴州站→宜章班车，转莽山班车。', '宜章汽车站→莽山班车，每天 4 班。', '导航“莽山国家森林公园”，停车 20 元。', NULL),
(31, '高椅岭丹霞环线', '湖南', 8, '丹霞', 'easy', '易', 6.2, 120, '3小时', '全年', 89, 1, '2-4 小时', 2.1, 262, 148, '红岩绿水的高椅背山脊，走一圈约 6 公里。日落时丹霞变成深红，是郴州最出片的免费野线。', '山脊无护栏，注意脚下；雨后红岩很滑；不要踩踏植被。', '广州南→郴州西站（1.5 小时），打车至高椅岭 40 分钟（60 元）。', '郴州站→资兴班车，高椅岭路口下。', '郴州汽车站→资兴班车，转摩的 10 分钟。', '导航“高椅岭风景区”，村口停车 10 元。', NULL),
(32, '崀山·八角寨—辣椒峰', '湖南', 12, '丹霞', 'mid', '中', 15, 530, '1天', '3-11月', 76, 0, '4-6 小时', 10.7, 820, 401, '世界自然遗产崀山，八角寨“一脚踏两省”，辣椒峰拔地而起。丹霞峰丛密集，是湖南最像桂林的地方。', '景区间需坐车，班次少，提前问末班时间；八角寨台阶陡。', '广州南→邵阳北站（2.5 小时），转新宁班车 2 小时。', '邵阳站→新宁班车，转崀山景区车。', '新宁汽车站→崀山，20 分钟一班。', '导航“崀山八角寨景区”，停车 15 元。', NULL),
(33, '大围山·七星岭', '湖南', 4, '森林山峰', 'mid', '中', 14.8, 1470, '1天', '4-11月', 78, 0, '6-8 小时', 12, 1607, 299, '浏阳河源头，4 月万亩杜鹃花海，冬季有雾凇。从栗木桥上山到七星岭，是长沙周边最像样的山地线。', '花期人多，建议早到；山顶无补给。', '长沙南→浏阳站（约 40 分钟），转大围山班车 1.5 小时。', '长沙站→浏阳班车，转大围山镇。', '浏阳汽车站→大围山班车，每天 6 班。', '导航“大围山国家森林公园”，停车 20 元。', NULL),
(34, '韭菜岭', '湖南', 13, '原始森林', 'hard', '难', 26, 1800, '2天', '5-10月', 74, 0, '8-10 小时', 8.6, 2009, 402, '湖南的“K2”，海拔 2009 米，都庞岭主峰。从月岩林场上山，经千家洞原始森林登顶，是湖南最难的一日/两日线之一。', '全程无补给，必须背水；林区多雨雾，易迷路；建议请向导。', '广州南→道州站（2.5 小时），包车至月岩林场 1 小时。', '道州站→清塘镇班车，转月岩林场。', '道县汽车站→清塘班车，每天 5 班。', '导航“道县月岩林场”，可停车。', NULL),
(35, '酃峰·神农谷', '湖南', 14, '原始森林', 'hard', '难', 22, 1360, '2天', '5-10月', 70, 0, '8-10 小时', 9.3, 2114, 701, '湖南最高峰 2115 米（神农峰），位于炎陵桃源洞保护区。从大院农场出发穿原始森林登顶，再下神农谷看瀑布群。', '保护区内需报备；蚂蟥多，穿长袜；无补给。', '长沙南→炎陵站（约 2 小时），包车至大院农场 1.5 小时。', '炎陵站→桃源洞班车，转大院。', '炎陵汽车站→桃源洞班车，每天 3 班。', '导航“炎陵大院农场”，可停车。', NULL),
(36, '八大公山', '湖南', 6, '原始森林', 'hard', '难', 21, 1780, '2天', '5-10月', 66, 0, '8-10 小时', 37.1, 1889, 300, '中国首批自然保护区，保存着亚热带最完整的原始常绿阔叶林。天平山、杉木界一线人迹罕至，是湖南最“野”的森林线。', '必须报备并请向导；林中无信号；蛇虫多。', '张家界西站→桑植班车 1.5 小时。', '张家界站→桑植班车，转保护区包车。', '桑植汽车站→八大公山班车，每天 2 班。', '导航“八大公山自然保护区”，山路弯多。', NULL),
(37, '壶瓶山', '湖南', 15, '峡谷山峰', 'hard', '难', 20, 2020, '1天', '4-10月', 65, 0, '8-10 小时', 4.7, 2099, 301, '湖南屋脊，主峰 2099 米。象鼻子沟峡谷溯溪上主峰，是湖南少见的“溪谷 + 登顶”组合，水量大时非常刺激。', '溯溪段需绳索；雨季禁止进沟；请向导。', '长沙南→石门县北站（2 小时），转壶瓶山班车 2 小时。', '石门县站→壶瓶山班车，每天 3 班。', '石门汽车站→壶瓶山，8:00/13:00 两班。', '导航“壶瓶山镇”，镇上停车。', NULL),
(38, '阳明山·万寿寺', '湖南', 13, '森林古道', 'easy', '易', 10.5, 930, '半天', '4-11月', 68, 0, '4-6 小时', 3, 1624, 799, '双牌阳明山以万亩杜鹃和万寿寺闻名，古道石阶缓上，4 月底花开时整座山都是粉红色，适合轻装半日。', '花期人多；山顶温度低 5℃。', '广州南→永州站（2.5 小时），转双牌班车 1 小时。', '永州站→双牌班车，转阳明山景区车。', '双牌汽车站→阳明山，每天 4 班。', '导航“阳明山国家森林公园”，停车 15 元。', NULL),
(39, '苏宝顶', '湖南', 16, '高山草甸', 'hard', '难', 24, 1830, '2天', '5-10月', 64, 0, '8-10 小时', 4.5, 1934, 300, '雪峰山主峰 1934 米，山顶是连片高山草甸与风电场，视野极好。从洪江上山，人少、原始，是湘西南的重装线。', '全程无补给；风车道路易迷路；雷雨天禁止上草甸。', '长沙南→怀化南站（2 小时），转洪江班车 1.5 小时。', '怀化站→洪江班车，转登山口包车。', '怀化汽车站→洪江，20 分钟一班。', '导航“洪江苏宝顶”，山路窄。', NULL),
(40, '舜皇山', '湖南', 13, '森林山峰', 'mid', '中', 15, 1770, '1天', '4-11月', 67, 0, '6-8 小时', 4.6, 1884, 303, '东安舜皇山，主峰 1882 米，相传舜帝南巡驻跸于此。森林密、溪流多，是湘南夏天避暑的徒步线。', '林区多雨，带雨衣；岔路多，跟紧路标。', '广州南→永州站，转东安班车 1 小时。', '东安东站→大庙口班车，每天 4 班。', '东安汽车站→大庙口，30 分钟一班。', '导航“东安舜皇山”，停车 10 元。', NULL);
INSERT INTO routes (id, name, province, city_id, terrain, level, level_text, distance_km, climb_m, days, season, heat, is_loop, hours_text, real_km, max_ele, min_ele, `desc`, tips, access_hsr, access_rail, access_bus, access_car, naming_json) VALUES
(41, '大熊山', '湖南', 17, '森林山峰', 'mid', '中', 16, 1260, '1天', '4-11月', 66, 0, '6-8 小时', 1.5, 1623, 502, '新化大熊山国家森林公园，主峰 1622 米，是蚩尤故里。森林覆盖率高，秋天枫香与银杏很好看。', '景区内道路长，建议坐车到半山再走；山顶风大。', '长沙南→新化南站（1.5 小时），转大熊山班车 1.5 小时。', '新化站→大熊山班车，每天 3 班。', '新化汽车站→大熊山，8:30/13:30 两班。', '导航“大熊山国家森林公园”。', NULL),
(42, '幕阜山', '湖南', 18, '山峰', 'mid', '中', 14, 1350, '1天', '4-11月', 63, 0, '6-8 小时', 2.3, 1598, 398, '湘鄂赣三省交界的幕阜山，主峰 1596 米，山势雄浑，山顶有古寺与高山湿地，是岳阳最值得走的山。', '山上多雾；部分路段为防火带，坡度大。', '长沙南→岳阳东站（40 分钟），转平江班车 2 小时。', '岳阳站→平江班车，转幕阜山。', '平江汽车站→幕阜山班车，每天 3 班。', '导航“幕阜山国家森林公园”。', NULL),
(43, '石牛寨', '湖南', 18, '丹霞', 'easy', '易', 7.5, 380, '半天', '全年', 71, 1, '2-4 小时', 1.5, 521, 198, '平江石牛寨的丹霞峰丛与玻璃桥，环线走完约 3 小时。山脊视野开阔，适合带家人轻徒步。', '玻璃桥需另购票；节假日排队久。', '长沙南→汨罗东站，打车至石牛寨 1 小时。', '岳阳站→平江班车，转石牛寨。', '平江汽车站→石牛寨班车，每天 5 班。', '导航“石牛寨景区”，停车 10 元。', NULL),
(44, '黑麋峰', '湖南', 4, '城市山', 'easy', '易', 8.5, 530, '半天', '全年', 69, 1, '2-4 小时', 2.1, 591, 119, '长沙近郊的滑翔伞基地，山顶风大视野好，环线 8 公里，是长沙人周末轻徒步的首选。', '山顶滑翔伞区域不要进入；夏天注意防晒。', '长沙南→地铁 2 号线转公交至望城，打车 20 分钟。', '长沙站→望城班车，转黑麋峰。', '望城汽车站→黑麋峰班车，每天 4 班。', '导航“黑麋峰国家森林公园”，停车 10 元。', NULL),
(45, '云台山（安化）', '湖南', 19, '茶山', 'mid', '中', 12, 900, '1天', '4-11月', 62, 0, '4-6 小时', 3, 1000, 198, '安化云台山以黑茶闻名，山路穿过连片茶园与云海，山顶玻璃栈道可俯瞰资江。走完可以直接下山喝茶。', '茶园段有农事活动，勿踩茶垄；山顶风大。', '长沙南→安化站（1.5 小时），转马路镇班车 1 小时。', '安化站→马路镇班车，每天 4 班。', '安化汽车站→马路镇，1 小时一班。', '导航“安化云台山”，停车 10 元。', NULL),
(46, '武功山·金顶穿越', '江西', 20, '高山草甸', 'hard', '难', 26, 1590, '2天', '9-11月', 98, 0, '8-10 小时', 15.6, 1918, 502, '国内最著名的高山草甸穿越。沈子村上山，经中庵、金顶、吊马桩到发云界，一路草甸连绵，秋季金黄。', '山脊无水源，需背水或住客栈；雷雨天禁止上草甸。', '萍乡北站→武功山景区直通车 1 小时（25 元）。', '萍乡站→武功山班车，40 分钟一班。', '萍乡汽车站→武功山，首班 6:30。', '导航“武功山游客中心”，停车 20 元/天。', NULL),
(47, '武功山·龙山村反穿', '江西', 20, '高山草甸', 'hard', '难', 24.5, 1470, '2天', '5-6月/9-11月', 93, 0, '8-10 小时', 19, 1918, 621, '从麻田龙山村起步，经发云界、好汉坡、绝望坡一路向西北推到金顶，比正穿少走 6 km 机耕道，草甸段更长。D1 住发云界，D2 上金顶后坐索道下撤。', '发云界到金顶之间有 4 个连续大坡（好汉坡、绝望坡），累计爬升集中；草甸段无树荫，夏天 10:00-15:00 暴晒，务必早出发。', '萍乡北站→武功山游客中心直通车 1 小时（25 元），再打车到龙山村 25 分钟（约 40 元）。', '萍乡站→麻田班车，途经龙山村路口，下车步行 10 分钟。', '萍乡汽车站→麻田，每天 6 班，末班 16:00，别错过。', '导航“麻田龙山村”，村口水泥坪可停 10 辆车，免费。', NULL),
(48, '武功山·金顶景区环线', '江西', 20, '高山草甸', 'easy', '易', 9.5, 1700, '1天', '全年（冬季看雾凇）', 90, 1, '4-6 小时', 9.4, 1912, 398, '坐索道到中庵，走石阶上金顶，再经福星谷栈道下山。全程铺装步道，是第一次看武功山草甸最省力的走法，也是带长辈小孩的唯一选择。', '索道 8:00 开始运行，节假日 9 点后排队 1 小时起；山顶比山下低 8-10℃，夏天也要带一件外套。', '萍乡北站→武功山游客中心直通车 1 小时（25 元），班次 8:00-17:00。', '萍乡站→武功山班车 40 分钟一班，票价 12 元。', '萍乡汽车站→武功山，首班 6:30，末班 17:30。', '导航“武功山游客中心”，停车 20 元/天，节假日 8 点前到才有位。', NULL),
(49, '黄山·天都峰环线', '安徽', 21, '花岗岩峰林', 'hard', '难', 18, 1100, '2天', '4-11月', 95, 1, '6-8 小时', 7.6, 1862, 833, '云谷寺上白鹅岭，经光明顶、天都峰、迎客松下山。天都峰鲫鱼背险峻，是黄山最刺激的一段。', '天都峰冬季封闭；鲫鱼背单向通行；山上住宿贵，需提前订。', '黄山北站→景区班车至汤口 1 小时（20 元）。', '黄山站→汤口班车，30 分钟一班。', '汤口换乘中心→云谷寺，20 分钟。', '导航“黄山风景区南大门换乘中心”。', NULL),
(50, '华山·五峰连穿', '陕西', 22, '花岗岩', 'hard', '难', 15, 1970, '1天', '4-10月', 94, 1, '6-8 小时', 4.9, 2155, 398, '自古华山一条路。玉泉院上山，经北峰、中峰、南峰、西峰，长空栈道与鹞子翻身是勇者的选择。', '长空栈道需另付 30 元并系安全带；夜爬看日出人多，注意保暖。', '西安北→华山北站（30 分钟），转景区公交 15 分钟。', '华山站→景区公交，20 分钟。', '华山北站→游客中心免费摆渡车。', '导航“华山游客中心”，停车 20 元/天。', NULL),
(51, '太白山·南北穿越', '陕西', 23, '高山石海', 'hard', '难', 42, 2650, '3天', '7-9月', 87, 0, '2 天', 12.2, 3769, 1402, '秦岭主峰拔仙台 3771 米，中国南北分界线。从塘口上山，经药王庙、大爷海到拔仙台，再从下板寺出山，是经典的三日重装线。', '高海拔天气突变，必须带硬壳与保暖；大爷海有接待站可住宿；需报备。', '西安北→眉县东站（1 小时），转汤峪班车 40 分钟。', '宝鸡站→太白县班车，转塘口。', '眉县汽车站→汤峪，30 分钟一班。', '导航“太白山塘口村”，村口停车。', NULL),
(52, '虎跳峡·高路', '云南', 24, '峡谷', 'mid', '中', 22, 980, '2天', '10-5月', 92, 0, '6-8 小时', 5.1, 2670, 1798, '世界最深峡谷之一的高路徒步，从桥头经纳西雅阁、28 道拐到中虎跳，一路俯瞰金沙江与玉龙雪山。', '28 道拐爬升集中；中虎跳下江边需走张老师栈道（¥30）。', '丽江站→虎跳峡班车 2 小时（40 元）。', '丽江站→桥头班车，每天 3 班。', '丽江客运站→香格里拉班车，桥头下。', '导航“虎跳峡桥头”，停车 10 元。', NULL),
(53, '雨崩神瀑', '云南', 24, '高原雪山', 'hard', '难', 36, 2570, '3天', '5-6月/9-10月', 90, 0, '2 天', 6.8, 3898, 2200, '梅里雪山脚下的世外村落。西当进村，经南宗垭口到上雨崩，第二天去冰湖，第三天到神瀑，是云南最经典的徒步线路。', '海拔 3000+，注意高反；村内住宿需提前订；尊重当地宗教习俗。', '丽江站→德钦班车 6 小时，转西当 1 小时。', '丽江→香格里拉班车，转德钦。', '德钦汽车站→西当班车，每天 2 班。', '导航“雨崩西当停车场”，山路险，谨慎驾驶。', NULL);
INSERT INTO route_waypoints (route_id, seq, name, lat, lng, ele, supply, note, photo, is_camp) VALUES
(1, 0, '罗坑镇', 24.575, 113.41, 110, '镇上小卖部、农家乐，最后的正经补给点，可寄存车辆', '集合点，海拔 110 米，从这里包车或步行进山。', NULL, 0),
(1, 1, '坪坑水电站', 24.545, 113.372, 320, '水电站有自来水，可灌水；无食物', '约 4.5 km 水泥路 + 机耕道，缓上。', NULL, 0),
(1, 2, '大坝山峡谷', 24.532, 113.352, 640, NULL, '进入峡谷段，溯溪石面湿滑，注意落石。', '峡谷巨石与溪流，逆光水雾很好拍', 0),
(1, 3, '乱石坡脚', 24.525, 113.32, 980, NULL, '连续碎石陡坡，1 km 爬升 400 m，是全段最耗体力的地方。', NULL, 0),
(1, 4, '船底顶主峰', 24.517, 113.283, 1586, NULL, '登顶。山顶草甸平缓，可扎 6-8 顶帐篷，风大需石堆压帐。', '草甸大斜坡 + 云海，日出机位在主峰东南侧', 0),
(1, 5, '坪坑坳营地', 24.523, 113.3, 1180, '季节性溪水，需过滤', '传统 D1 营地，避风，可容纳 10 顶帐篷。', NULL, 1),
(1, 6, '新洞村', 24.56, 113.315, 300, '村口有农家可叫车，旺季有摩托接驳', '下山出口，机耕道 5 km 出村。', NULL, 0),
(2, 0, '联山小学', 24.615, 113.315, 260, '村中小卖部可补水', '起点，沿防火带上山。', NULL, 0),
(2, 1, '第一草坡', 24.588, 113.3, 860, NULL, '连续草坡，坡度 30° 左右，注意脚下浮石。', NULL, 0),
(2, 2, '船底顶主峰', 24.517, 113.283, 1586, NULL, '登顶后向西南方向下撤。', '主峰草甸全景，云海概率高', 0),
(2, 3, '坪坑坳营地', 24.523, 113.3, 1180, '溪水需过滤', '营地平坦避风。', NULL, 1),
(2, 4, '坪坑水电站', 24.545, 113.372, 320, '可灌自来水', '机耕道下山。', NULL, 0),
(2, 5, '罗坑镇', 24.575, 113.41, 110, '农家乐、包车', '终点，可洗澡吃饭。', NULL, 0),
(3, 0, '龙岩寺', 23.05, 114.905, 120, '寺内有水，可停车', '起点，石阶路上行 1.2 km。', NULL, 0),
(3, 1, '大南山草甸', 23.075, 114.885, 780, NULL, '进入草甸，视野打开。', '草甸大斜坡，逆光拍剪影', 0),
(3, 2, '水底山鞍部', 23.09, 114.865, 1010, NULL, '山脊岔口，右转上主峰。', NULL, 0),
(3, 3, '大南山主峰', 23.098, 114.855, 1105, NULL, '最高点，风大。', '360° 草甸，日出/日落机位', 0),
(3, 4, '大南山村', 23.105, 114.845, 420, '村口小卖部、农家乐', '沿防火带下山回村。', NULL, 0),
(4, 0, '白云嶂山脚', 22.875, 114.315, 90, '山脚农庄可停车、吃饭', '起点，水泥路缓上。', NULL, 0),
(4, 1, '白云嶂顶', 22.885, 114.3, 1003, NULL, '第一座千米峰。', '山顶巨石群，可俯瞰东莞', 0),
(4, 2, '银瓶嘴', 22.9, 114.325, 898, NULL, '沿山脊东行 3 km 到第二峰。', '山脊草坡与三城同框', 0),
(4, 3, '盘古宫', 22.87, 114.29, 120, '宫前有自来水', '石阶下山出口。', NULL, 0),
(5, 0, '朱明洞景区', 23.272, 114.072, 60, '景区商铺、洗手间', '起点，购票入园（¥55）。', NULL, 0),
(5, 1, '缆车下站', 23.278, 114.062, 320, '小卖部、饮用水', '可坐缆车省 1 小时，也可走古道。', NULL, 0),
