INSERT INTO app_versions (code, released_at, tag, title, summary, snapshot, live_url, metrics) VALUES
('v2', '2026-11-06 09:52', '上一次', '静态内容站：路线勘误 + 大图双击修复', '纯前端内容站：76 个点位、53 条路线、74 项装备，双底图与四季图集齐；修好详情页大图双击，「双击看大图」提示改为悬停出现；岳麓山·桃花岭穿越补了起终点勘误卡。', '2026-11-06_0952', '', '[{"k":"点位 / 路线","v":"76 / 53"},{"k":"装备条目","v":"74"},{"k":"封面图","v":"110 张（≥1200px）"},{"k":"四季 / 日落夜景","v":"304 / 150 张"},{"k":"账号能力","v":"无"},{"k":"收藏能力","v":"无"}]'),
('v3', '2026-11-06 13:10', '本次', '账号体系 + 收藏 + 版本对比页 + 导航图标重做', '从「只能看」升级为「能存下来」：本地账号（注册 / 登录 / 30 分钟滑动会话）、景点与路线收藏、我的收藏页；顶部五个版块图标换成手绘 SVG 并加了悬停动效；新增本页，用来逐轮对比数据与效果。', '2026-11-06_1748', 'https://south-china-hiking.app.workbuddy.host/?sharecode=NXC6GS3IF3', '[{"k":"页面路由","v":"9 个"},{"k":"新增组件","v":"3 个（AuthDialog / NavIcon / 版本页）"},{"k":"新增 store","v":"3 个（auth / fav / ui）"},{"k":"导航图标","v":"6 枚手绘 SVG + 动效"},{"k":"账号能力","v":"注册 · 登录 · 登出 · 会话续期"},{"k":"收藏能力","v":"景点 / 路线，按账号隔离"}]');
